/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var debug = logger( 'plot:view:browser:routes:width' );


// MAIN //

/**
* Callback invoked upon receiving an HTTP request.
*
* @private
* @param {Object} request - request object
* @param {Object} response - response object
* @param {Callback} next - callback to invoke upon completion
* @returns {void}
*/
function handler( request, response, next ) {
	var body = request.body;

	debug( 'New value: %s', body );
	try {
		this.plot.width = parseInt( body, 10 );
	} catch ( err ) {
		debug( 'Encountered an error when attempting to assign value. Error: %s', err.message );
		return next({
			'statusCode': 400,
			'error': 'Bad Request',
			'message': format( 'Invalid value: %s', body )
		});
	}
	next();
}


// EXPORTS //

module.exports = handler;
